    [39] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "I wasn't expecting Gavin to try intimidating me by pulling rank. I shifted in place for a moment, then finally went carefully toward him, maintaining a modicum of space from him.",
      next = {40}
    },
    [40] = {
      beijing = 3732,
      dhead = 1512,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "It's so... quiet here.",
      next = {41}
    },
    [41] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Because the flames of war burned everything down two years ago.",
      voice = 2,
      next = {42}
    },
    [42] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "I raised my head in shock and looked at Gavin. The thin moonlight enveloped his brow, but it looked more like a crust of frost formed from the cold fires of hell.",
      next = {43}
    },
    [43] = {
      beijing = 3732,
      dhead = 1511,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "This place... was where the Battle of Jade Gate took place?",
      next = {44}
    },
    [44] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "You can't really tell now, but back then it was occupied by the Rongdi.",
      voice = 2,
      next = {45}
    },
    [45] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Then, after three days of bloody battle, the Sparrow Army made sure the Rongdi and their scimitars would never push another inch past Jade Gate.",
      voice = 2,
      next = {46}
    },
    [46] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      ruchang = 9,
      sentence = "Fifty thousand soldiers. They were born in the state of Yu, and buried in this soil.",
      voice = 2,
      next = {47}
    },
    [47] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "The night wind brushed over my face. I looked in a daze at the freezing cold, yet burning hot flowers that bloomed like flames and were soaked in blood, and lit up this entire land.",
      next = {48}
    },
    [48] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "I had previously pored over every battle report that came out at the time. I knew every detail about the Battle of Jade Gate, and every person that died.",
      next = {49}
    },
    [49] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "The words of these reports when told through Gavin's voice seeped into my bones and blood, giving a completely different feeling from when I'd first read them.",
      next = {50}
    },
    [50] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "All of a sudden, I seemed to understand why Gavin brought me here himself. I looked at him with his thick armor and that far-away, lonely look on his face.",
      next = {51}
    },
    [51] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "At my inspector's desk, I had read through the Camp Sparrow archives, and I knew that under this armor was a body full of old wounds.",
      next = {52}
    },
    [52] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "But aside from the old injuries that wouldn't heal, that major battle also left a fire raging in his heart for two years.",
      next = {53}
    },
    [53] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "The icy wind wailed like an elegy, but also like the ditty of a soldier thinking of his home. I listened intently for a moment, then started singing softly:",
      next = {54}
    },
    [54] = {
      beijing = 3732,
      dhead = 1507,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      sentence = "\"Spring days sprinkle by, and lush foliage springs up. Orioles chirp as the women flock to gather wormwood.\"",
      next = {55}
    },
    [55] = {
      beijing = 3732,
      dhead = 1507,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      sentence = "\"With captives and prisoners in tow we return. The magnificent Nanzhong has pacified Xianyun.\"",
      next = {56}
    },
    [56] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402208,
      role5 = 4118401,
      ruchang = -1,
      sentence = "Hearing my little verse, Gavin was taken aback for a moment. The he looked at me with eyes as gentle as starlight and a voice as soft as a breeze.",
      next = {57}
    },
    [57] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "When duty calls, one must answer. No one wants a war, yet the imperial order is absolute.",
      voice = 2,
      next = {58}
    },
    [58] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      ruchang = 9,
      sentence = "Back at Grandletter Academy, we learned that poem about soldiers yearning for home.",
      voice = 2,
      next = {59}
    },
    [59] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      sentence = "I held back the stinging feeling in my chest and looked out on the field of sandthorn flowers.",
      next = {60}
    },
    [60] = {
      beijing = 3732,
      dhead = 1508,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      sentence = "Your Highness, fifty thousand souls rest here at the Jade Gate. They're already home. They're not worrying anymore about going home.",
      next = {61}
    },
    [61] = {
      beijing = 3732,
      dhead = 1508,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      sentence = "You lived through the Battle of Jade Gate, but the whole story of this battle didn't just unfold on the frontlines. Do you want to hear about it from my perspective, Your Highness?",
      next = {62}
    },
    [62] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      ruchang = -1,
      sentence = "Gavin's eyes flashed, and he stared at me with the utmost earnestness, as if he wanted to plumb the depths of my eyes for everything I'd been through these past three years.",
      next = {63}
    },
    [63] = {
      beijing = 3732,
      dhead = 1506,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Although I was still at Grandletter Academy then, I was able to see the battle reports at the time with the help of a classmate in the army.",
      next = {64}
    },
    [64] = {
      beijing = 3732,
      dhead = 1506,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "At the time, the entire army was annihilated, and only Your Majesty made it back alive. The peace-advocating faction in the court blocked a motion to send reinforcements to your rescue, which led to you having to fight your way out from certain death.",
      next = {65}
    },
    [65] = {
      beijing = 3732,
      dhead = 1506,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "You were in a coma for days before you woke up...",
      next = {66}
    },
    [66] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "As I mentioned this, I could still feel that fear in my heart. Gavin had been pierced in the chest by an arrow from the enemy commander, and when he made it back to Camp Sparrow, he was gasping his last breaths.",
      next = {67}
    },
    [67] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "I steadied my trembling voice and continued on:",
      next = {68}
    },
    [68] = {
      beijing = 3732,
      dhead = 1506,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "...His Majesty decided to hold back his army in order to let the Rongdi wear themselves thin at Jade Gate, after which he could dispatch soldiers from the southwest and catch them off guard.",
      next = {69}
    },
    [69] = {
      beijing = 3732,
      dhead = 1506,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "It wasn't that he didn't give a fig about your life. He was only looking at the bigger picture.",
      next = {70}
    },
    [70] = {
      beijing = 3732,
      dhead = 1506,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "I know full well that as far as the royal court is concerned, they wouldn't mind trading each life in Camp Sparrow for just an inch of land at the border.",
      next = {71}
    },
    [71] = {
      beijing = 3732,
      dhead = 1502,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "But lives shouldn't be counted so simply. Many court officials admire your strength of character from afar and are rooting for you in the court.",
      next = {72}
    },
    [72] = {
      beijing = 3732,
      dhead = 1502,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "And all the hard work of the court will be thrown to the winds if you don't stay safe.",
      next = {73}
    },
    [73] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "As he listened to me say this, Gavin's gaze fell on my cheeks like the gentlest winds in the Northlands.",
      next = {74}
    },
    [74] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "I know. And I understand what you're trying to warn me about, but this battle is inevitable.",
      voice = 2,
      next = {75}
    },
    [75] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "All I can promise you is this:",
      voice = 2,
      next = {76}
    },
    [76] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "At some point, a pallid mist had sprung up above the land. His tone was as firm as monolith, each word like a bulwark against the buffeting winds.",
      next = {77}
    },
    [77] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Even if I am down to my last breath, I will make it back alive.",
      voice = 2,
      next = {78}
    },
    [78] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "But when that time comes, there is something I want you to answer.",
      voice = 2,
      next = {79}
    },
    [79] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "My heart fluttered as I looked into his determined eyes.",
      next = {80}
    },
    [80] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Back then at Grandletter Academy, you clearly yearned for freedom. You wanted to see the wide world, not be shut up in a gilded cage.",
      voice = 2,
      next = {81}
    },
    [81] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "So in the end, why did you choose to become a court official?",
      voice = 2,
      next = {82}
    },
    [82] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "His words stirred up a thousand ripples in my heart. I thought back to our curiosity about the world back then and how I once told Gavin that someday I would see it all with my own eyes.",
      next = {83}
    },
    [83] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "If it wasn't for the Battle of Jade Gate and that edict, perhaps today I would be here visiting him of my own accord.",
      next = {84}
    },
    [84] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Vast deserts and long rivers. Armed soldiers and war horses. As long as I could be by his side, I would go anywhere.",
      next = {85}
    },
    [85] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "I suddenly got the urge to blurt all this out to him, but ultimately, we were no longer the same people from back in Grandletter Academy.",
      next = {86}
    },
    [86] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "All I could do was bite my lip and not let a hint of my softhearted weakness slip out. Seeing me hesitate, Gavin changed the subject.",
      next = {87}
    },
    [87] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118107,
      role3 = 402206,
      role5 = 4118401,
      sentence = "Three years ago, the Rongdi killed the general at the border and began a massive invasion. The court had no general they could send, so I requested to lead the troops to the pass.",
      voice = 2,
      next = {88}
    },
    [88] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "That last night in Grandletter Academy, you threw a little goodbye party for me, remember?",
      voice = 2,
      next = {89}
    },
    [89] = {
      beijing = 3732,
      dhead = 1508,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      sentence = "...I remember.",
      next = {90}
    },
    [90] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      roleanim = 1.1,
      sentence = "As I whispered my answer, Gavin suddenly scooted closer to me. I was literally taken aback and started moving away, but he grabbed my wrist.",
      next = {91}
    },
    [91] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      roleanim = 1.1,
      sentence = "Our eyes locked. He lifted a hand to push my wind-blown bangs back behind my ear, and then I heard his soft voice:",
      next = {92}
    },
    [92] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      roleanim = 1.1,
      sentence = "That night, I made myself a promise. That when I got back, I would tell you.",
      voice = 2,
      next = {93}
    },
    [93] = {
      beijing = 3732,
      dialog = 2,
      idx = 4,
      male = 4,
      music = "25_Romantic_Quiet_MAS",
      renming = "Gavin",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      roleanim = 1.1,
      sentence = "Now promise me, you'll give me the answer to my question too.",
      voice = 2,
      next = {94}
    },
    [94] = {
      beijing = 3732,
      dialog = 3,
      music = "25_Romantic_Quiet_MAS",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      roleanim = 1.1,
      sentence = "He undid the pouch of wine at his waist and handed it to me. I wanted to demur, but seeing that fiery look in his eye, I couldn't help but take the wine skin and give him a nod.",
      next = {95}
    },
    [95] = {
      beijing = 3732,
      dhead = 1501,
      dialog = 1,
      music = "25_Romantic_Quiet_MAS",
      renming = "$u",
      renwu = "npc",
      role1 = 4118000,
      role2 = 4118108,
      role3 = 402206,
      role5 = 4118401,
      roleanim = 1.1,
      sentence = "I promise you.",
      next = {96}
    },
    [96] = {
      beijing = 2022,
      bganim = 0,
      dialog = 3,
